import Foundation

/// Fictional source text and controls only; no production knowledge or client fixtures.
enum ReviewedScopeTests {
    static let fixtureData = Data(base64Encoded: "")!
    static let legacyData = Data(base64Encoded: "")!
    static func envelope(_ id: String) throws -> Data {
        let text = String(decoding: try JSONSerialization.data(withJSONObject: ["mode":"answer", "unit_id":id]), as: UTF8.self)
        return try JSONSerialization.data(withJSONObject: ["content":[["type":"text","text":text]], "stop_reason":"end_turn"])
    }
    static func run(_ check: (String, Bool) -> Void) {
        do {
            let catalog = try ReviewedAnswerCatalog.decode(fixtureData)
            let docs = catalog.sources.map { KBDocument(name:$0.name, chunkCount:1, addedAt:.now, contentSHA256:$0.sha256) }
            let snapshot = catalog.admitted(documents:docs, folders:[], profileID:nil)
            check("scope: authenticated v2 admits four synthetic whole replies", snapshot.answers.count == 4)
            let complete = catalog.answers[0], vendor = catalog.answers[1], unrelated = catalog.answers[2], capability = catalog.answers[3]
            let productQuestion = "Can I map Role A and Role B to separate styles?"
            let vendorQuestion = "Can two text containers share the same definition?"
            let procedure = "How do I assign separate styles to Role A and Role B?"
            let productCandidates = snapshot.candidates(question:productQuestion, referenceNames:[])
            check("scope: product candidates exclude vendor and unrelated product", Set(productCandidates.map(\.id)) == Set([complete.id, capability.id]))
            check("scope: procedure excludes a capability-only fact", snapshot.candidates(question:procedure, referenceNames:[]).map(\.id) == [complete.id])
            check("scope: vendor fundamental remains eligible", snapshot.candidates(question:vendorQuestion, referenceNames:[]).map(\.id) == [vendor.id])
            check("scope: version still constrains a routed answer", snapshot.candidates(question:productQuestion+" In version 9.9.9.", referenceNames:[]).isEmpty)
            check("scope: supported compound forms use the complete instruction", snapshot.candidates(question:"Can I map Role A and Role B, and how do I choose their styles?", referenceNames:[]).map(\.id) == [complete.id])
            for question in ["Can I map Role A and Role B now?", "Does the budget update from Refresh now?"] {
                check("scope: current availability cannot use a general product fact: "+question,
                      snapshot.candidates(question:question, referenceNames:[]).isEmpty)
            }
            for question in ["Can I map Role A and Role B? Also where do I find those controls?", "Can I map Role A and Role B, but where is that option?", "Can I map Role A and Role B? Also, where do I find it?"] {
                check("scope: prefaced second question cannot be omitted: "+question,
                      snapshot.candidates(question:question, referenceNames:[]).isEmpty)
            }
            for question in ["Can I map Role A and Role B and update the budget?", "Can I not map Role A and Role B?", "Can I choose unrelated text styles?", "Did our panel map Role A and Role B?", "Can I map Role A and Role B, and where do I find those controls?", "Can I map Role A and Role B, and who changed them last?", "Can I map Role A and Role B, and whose styles were selected?", "Does my budget update from Refresh?", "Will my budget update from Refresh?", "Was our budget updated from Refresh?", "The quote says \"Can I map Role A and Role B?\". Is that true?"] {
                check("scope: ambiguous, negated, state or quoted question fails closed: "+question, snapshot.candidates(question:question, referenceNames:[]).isEmpty)
            }
            var off = docs[2]; off.scope = .off
            let missingTopic = catalog.admitted(documents:[docs[0], docs[1], off], folders:[], profileID:nil)
            check("scope: unavailable topic cannot disappear from compound routing", missingTopic.candidates(question:"Can I map Role A and Role B and update the budget?", referenceNames:[]).isEmpty)
            func selected(_ answer: ReviewedAnswerCatalog.Answer, _ question: String) throws -> InsightDraft {
                var request = AnalysisRequest(transcript:"Them: "+question, currentQuestion:question, knownInsightTitles:[], references:[], instructions:"", callBrief:"", allowGeneralKnowledge:false, knownDocumentNames:docs.map(\.name), persona:"Synthetic test", counterpart:"client", kinds:[], gauges:[])
                request.reviewedCatalog = snapshot; request.reviewedQuestionKey = question
                // Intentionally supply every admitted unit to test the final boundary.
                return ClaudeAnalysisProvider.reviewedAnswerDraft(from:try envelope(answer.id), request:request, catalog:snapshot, candidates:snapshot.answers)
            }
            check("scope: forced wrong-authority ID is rejected", try selected(vendor, productQuestion).source == nil)
            check("scope: forced unrelated product ID is rejected", try selected(unrelated, productQuestion).source == nil)
            check("scope: forced capability-only ID cannot answer a procedure", try selected(capability, procedure).source == nil)
            check("scope: valid product wording stays exact", try selected(complete, productQuestion).reply == complete.reply)
            check("scope: valid vendor wording stays exact", try selected(vendor, vendorQuestion).reply == vendor.reply)
            check("scope: forced unit cannot answer a multi-scope question", try selected(complete, "Can I map Role A and Role B and update the budget?").source == nil)
            check("scope: partial words cannot select a reviewed route", snapshot.candidates(question:"Can I remap Role A and Role B?", referenceNames:[]).isEmpty)
        } catch { check("scope: valid v2 fixture error "+error.localizedDescription, false) }
        for question in ["Does my file include an image?", "Is the Sample document using the selected style?", "Which styles are currently selected in this file?", "Who last edited our publication?", "Will our account receive this change?", "Is Role A enabled?", "Is the option turned on?", "Are the styles active?", "Is Role A available in my account?", "Where are the photos in our publication now?"] {
            check("scope: actual-file/state form is explicit: "+question,
                  ReviewedQuestionForm.forms(in:question).contains(.clientState))
        }
        check("scope: a general document behavior is not client state",
              ReviewedQuestionForm.forms(in:"Does a document use shared definitions?") == [.behavior])
        check("scope: an instruction about my document remains a procedure",
              ReviewedQuestionForm.forms(in:"How do I change a style in my document?") == [.procedure])
        for question in ["Is it available now?", "Is it already changed?", "Does Role A work now?", "Can I use it yet?", "Does it work anymore?", "Can I use it currently?", "Should I use it yet?", "Should we use it now?"] {
            check("scope: temporal auxiliary form requires current client state: "+question,
                  ReviewedQuestionForm.forms(in:question).contains(.clientState))
        }
        check("scope: a how-to remains a general instruction despite now",
              ReviewedQuestionForm.forms(in:"How can I use it now?") == [.procedure])
        for (name, data, reason) in invalidFixtures {
            do { _ = try ReviewedAnswerCatalog.decode(data); check("scope: signed invalid "+name, false) }
            catch { check("scope: signed invalid "+name, error.localizedDescription.contains(reason)) }
        }
        do { _ = try ReviewedAnswerCatalog.decode(legacyData); check("scope: signed v1 cannot infer new review metadata", false) }
        catch { check("scope: signed v1 cannot infer new review metadata", true) }
        do {
            let envelope = try JSONSerialization.jsonObject(with:fixtureData) as! [String:Any]
            let payload = Data(base64Encoded:envelope["payload"] as! String)!
            let original = try JSONSerialization.jsonObject(with:payload) as! [String:Any]
            for key in ["authority", "scope", "supportedForms"] {
                var changed = original
                if key == "authority" { var sources = changed["sources"] as! [[String:Any]]; sources[0].removeValue(forKey:key); changed["sources"] = sources }
                else { var answers = changed["answers"] as! [[String:Any]]; answers[0].removeValue(forKey:key); changed["answers"] = answers }
                let raw = try JSONSerialization.data(withJSONObject:changed)
                check("scope: required raw metadata cannot default: "+key, (try? JSONDecoder().decode(ReviewedAnswerCatalog.self, from:raw)) == nil)
            }
        } catch { check("scope: raw required-field test error", false) }
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("parrot-scope-store-"+UUID().uuidString)
        do {
            try FileManager.default.createDirectory(at:directory, withIntermediateDirectories:true)
            defer { try? FileManager.default.removeItem(at:directory) }
            let url = directory.appendingPathComponent("library.json")
            try legacyData.write(to:url)
            let store = ReviewedAnswerStore(url:url)
            do { _ = try store.load(); check("scope: saved v1 rejected", false) } catch { check("scope: saved v1 rejected", true) }
            check("scope: v1 rejection records durable reviewed intent", store.isConfigured && FileManager.default.fileExists(atPath:store.requiredURL.path))
            try FileManager.default.removeItem(at:url)
            do { _ = try ReviewedAnswerStore(url:url).load(); check("scope: v1 removal cannot restore free generation", false) } catch { check("scope: v1 removal cannot restore free generation", true) }
        } catch { check("scope: store test error "+error.localizedDescription, false) }
    }
    static let invalidFixtures: [(String, Data, String)] = [
        ("scope-changed", Data(base64Encoded:"")!, "answer identity changed"),
        ("forms-changed", Data(base64Encoded:"")!, "answer identity changed"),
        ("authority-changed", Data(base64Encoded:"")!, "source identity changed"),
        ("authority-mismatch", Data(base64Encoded:"")!, "scope authority mismatch"),
        ("scope-definition-conflict", Data(base64Encoded:"")!, "conflicting scope definitions"),
        ("scope-too-broad", Data(base64Encoded:"")!, "invalid reviewed question scope"),
        ("client-state-fact", Data(base64Encoded:"")!, "unverified client-state"),
    ]
}
